#!/usr/bin/env node
/**
 * gen-api-reference — the REST reference, generated from the server's own router.
 *
 *   node scripts/gen-api-reference.mjs           # (re)write the generated files
 *   node scripts/gen-api-reference.mjs --check   # exit 1 if they are out of date
 *   node scripts/gen-api-reference.mjs --stats   # print the route counts, write nothing
 *
 * Source: the app itself. scripts/api-reference-walk.cjs loads server/index.js
 *         with the database stubbed (the same walk server/auth/routeWalk.cli.js
 *         gives the access-registry tests) and reports every mounted route with
 *         its authorization gates and the zod schemas of its
 *         `validate({ body, query, params })`, converted to JSON Schema.
 *         Nothing in server/ is read as text and nothing there is changed.
 * Output: docs/static/openapi.json                 OpenAPI 3.1, served at /openapi.json
 *         docs/docs/api/reference.md               the overview page
 *         docs/docs/api/reference/*.md             one page per area, for the docs site
 *
 * Routes without a `validate(...)` schema are listed with "no request schema":
 * they may still check their input by hand. The gates are what the middleware
 * chain enforces; a handler can check more inside its body.
 *
 * Deterministic: routes are sorted, the environment of the walk is fixed and a
 * local .env is ignored, so --check gives the same answer on every machine. It
 * needs server/node_modules (the walk loads the app), so check:fast leaves it
 * out and ci.yml's server-checks job runs it (`npm run lint:api-reference`).
 *
 * Zero dependencies of its own: node:* only.
 */

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { isEntryPoint } from './entry-point.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SERVER = path.join(ROOT, 'server');
const WALKER = path.join(ROOT, 'scripts', 'api-reference-walk.cjs');

export const OPENAPI_REL = 'docs/static/openapi.json';
export const PAGES_REL = 'docs/docs/api/reference';
// Beside the folder, not in it: an index.md inside an autogenerated sidebar folder
// shows up twice (as the category link and as an item of its own).
export const INDEX_REL = 'docs/docs/api/reference.md';
const OPENAPI_PUBLIC = '/openapi.json';

/** A group with fewer routes than this shares the "other" page. */
export const MIN_PAGE_ROUTES = 10;
/** Rows per request part in a page; the OpenAPI file always has the full schema. */
const MAX_ROWS = 60;
/** How deep a nested object is flattened into dotted rows. */
const MAX_DEPTH = 3;

const REGENERATE = 'node scripts/gen-api-reference.mjs';
const GENERATED_NOTE = `Generated by scripts/gen-api-reference.mjs from the server's router. Do not edit by hand: change the route, then run \`${REGENERATE}\`.`;

const METHOD_ORDER = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'];
const OPENAPI_METHODS = new Set(METHOD_ORDER);

/**
 * The environment of the walk: fixed, so the answer does not depend on the
 * machine. The dummy secrets only let the stores load; they authenticate nothing.
 * The three flags mount the opt-in MCP endpoints so they are listed too.
 */
export function walkEnv(base = process.env) {
    const env = {
        NODE_ENV: 'test',
        OTEL_ENABLED: 'false',
        SESSION_SECRET: 'api-reference-walk-dummy-secret-0123456789',
        MASTER_ENCRYPTION_KEY: 'api-reference-walk-dummy-secret-0123456789',
        AUTOMATION_MCP_ENABLED: '1',
        STUDIO_MCP_ENABLED: '1',
        CMS_MCP_ENABLED: '1',
    };
    for (const key of ['PATH', 'HOME', 'TMPDIR', 'SystemRoot', 'TEMP', 'TMP']) {
        if (base[key]) env[key] = base[key];
    }
    return env;
}

/** Run the walk in a child process; returns the raw route table. */
export function walkServer({ server = SERVER, walker = WALKER, spawn = spawnSync } = {}) {
    if (!fs.existsSync(path.join(server, 'node_modules'))) {
        throw new Error('server/node_modules is missing: the walk loads the app. Run `cd server && npm ci` first.');
    }
    const out = path.join(os.tmpdir(), `bf-api-reference-${process.pid}.json`);
    try {
        const res = spawn(process.execPath, [walker, out], {
            cwd: server,
            env: walkEnv(),
            encoding: 'utf8',
            timeout: 180_000,
            maxBuffer: 64 * 1024 * 1024,
        });
        if (res.status !== 0) {
            const tail = String(res.stderr || res.stdout || res.error || '').split('\n').slice(-25).join('\n');
            throw new Error(`the route walk failed (exit ${res.status}):\n${tail}`);
        }
        return JSON.parse(fs.readFileSync(out, 'utf8'));
    } finally {
        fs.rmSync(out, { force: true });
    }
}

// ── The model ────────────────────────────────────────────────────────

const methodRank = (m) => {
    const i = METHOD_ORDER.indexOf(m);
    return i === -1 ? METHOD_ORDER.length : i;
};

/** A path that is a plain `/a/:b/*c` shape, not a regular expression. */
export function isPlainPath(p) {
    return typeof p === 'string' && p.startsWith('/') && !/[()^$\\?]/.test(p);
}

/** `/a/:id/{*rest}` or `/a/*rest` → `/a/{id}/{rest}`. */
export function openapiPath(p) {
    return p
        .replace(/\{\*([A-Za-z0-9_]+)\}/g, '{$1}')
        .replace(/\*([A-Za-z0-9_]+)/g, '{$1}')
        .replace(/:([A-Za-z0-9_]+)/g, '{$1}');
}

export function pathParamNames(p) {
    return [...openapiPath(p).matchAll(/\{([A-Za-z0-9_]+)\}/g)].map((m) => m[1]);
}

/** The area a route belongs to: `/api/automation/x` → `api/automation`, `/auth/x` → `auth`. */
export function groupOf(p) {
    const segs = p.split('/').filter(Boolean);
    if (!isPlainPath(p) || segs.length === 0) return '';
    const first = segs[0];
    if (/^[:*{]/.test(first)) return '';
    if (first === 'api' && segs[1] && !/^[:*{]/.test(segs[1])) return `api/${segs[1]}`;
    return first;
}

/**
 * Sorted, de-duplicated routes. The same method and path reachable twice (two
 * mounts of one router, or a public mount ahead of a gated one) is one entry, and
 * it is the FIRST one in walk order: Express answers from the first match, so its
 * gates and schemas are the ones that apply. Merging them would let a gated twin
 * hide a public route.
 */
export function normaliseRoutes(raw) {
    const byKey = new Map();
    for (const r of raw.routes) {
        const method = r.method === '_ALL' ? 'ALL' : r.method;
        const key = `${method} ${r.path}`;
        if (byKey.has(key)) continue;
        byKey.set(key, {
            method,
            path: r.path,
            gates: r.gates || [],
            middleware: r.middleware || [],
            schemas: r.schemas || {},
            probedHandler: Boolean(r.probedHandler),
        });
    }
    return [...byKey.values()]
        .map((r) => ({ ...r, group: groupOf(r.path) }))
        .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : methodRank(a.method) - methodRank(b.method) || a.method.localeCompare(b.method)));
}

export function hasSchema(route) {
    return Object.keys(route.schemas).length > 0;
}

/** Gates that say who may call (module and org-status gates are plumbing, not access). */
const ACCESS_AXES = new Set(['auth', 'rbac', 'platform', 'scope', 'scoped', 'license', 'capability']);

const backtick = (s) => `\`${s}\``;

/** One short phrase per gate. */
export function describeGate(g) {
    switch (g.axis) {
        case 'auth': return 'Signed-in user';
        case 'platform': return g.kind === 'superAdmin' ? 'Platform admin' : `Platform ${g.kind}`;
        case 'rbac': {
            const perms = (g.anyOf || []).filter((p) => p !== 'all');
            return perms.length ? `Permission ${perms.map(backtick).join(' or ')}` : 'Platform admin';
        }
        case 'scope': {
            if (g.kind === 'orgAdminOfOwnOrg') return 'Admin of their own organisation';
            if (g.kind === 'orgAdminOfParam') return `Admin of the organisation in ${backtick(`:${g.param}`)}`;
            if (g.kind === 'orgAdminOfTargetUser') return 'Admin of the target user\'s organisation';
            return `Scope ${backtick(g.kind)}`;
        }
        case 'scoped': return `Resource role ${backtick(g.minGrade)} or higher`;
        case 'license': return `Licence feature ${backtick(g.feature)}`;
        case 'capability': return `Capability ${backtick(g.id)}`;
        default: return `${g.axis} ${backtick(g.id || g.kind || '')}`.trim();
    }
}

/** Who first, then what: a stable order whatever order the middleware sits in. */
const AXIS_RANK = ['auth', 'platform', 'rbac', 'scope', 'scoped', 'license', 'capability'];

/** What the middleware chain demands, as phrases; empty when it demands nothing. */
export function accessPhrases(route) {
    const out = [];
    const gates = route.gates.filter((g) => ACCESS_AXES.has(g.axis));
    gates.sort((a, b) => AXIS_RANK.indexOf(a.axis) - AXIS_RANK.indexOf(b.axis));
    for (const g of gates) {
        const phrase = describeGate(g);
        if (!out.includes(phrase)) out.push(phrase);
    }
    return out;
}

/**
 * The whole access line of a route, as prose. Gates are what the tagged
 * middleware enforces; untagged named middleware is listed by name; a route with
 * neither is decided in the handler (a session check inside it, or public).
 */
export function accessLine(route) {
    const parts = [];
    const gates = accessPhrases(route);
    if (gates.length) parts.push(gates.join(' · '));
    if (route.middleware.length) parts.push(`middleware ${route.middleware.map(backtick).join(', ')}`);
    if (parts.length === 0 && route.path.startsWith('/mcp')) {
        return 'a bearer MCP token (or an upload ticket), checked by the handler';
    }
    if (parts.length === 0) {
        return 'no gate in the middleware chain: the handler decides (it checks the session itself, or the route is public)';
    }
    const line = parts.join(' · ');
    return route.probedHandler ? `${line} · the handler also checks who the caller is` : line;
}

export function requiresSession(route) {
    return route.gates.some((g) => ACCESS_AXES.has(g.axis));
}

// ── OpenAPI ──────────────────────────────────────────────────────────

const sortKeys = (value) => {
    if (Array.isArray(value)) return value.map(sortKeys);
    if (value && typeof value === 'object') {
        return Object.fromEntries(Object.keys(value).sort().map((k) => [k, sortKeys(value[k])]));
    }
    return value;
};

/** `get_api_automation_{id}_runs`: readable, and unique per method and path. */
const operationId = (route) => `${route.method.toLowerCase()}${openapiPath(route.path).replace(/[^A-Za-z0-9{}-]+/g, '_')}`;

function parametersOf(route) {
    const params = [];
    const declared = route.schemas.params && route.schemas.params.properties ? route.schemas.params.properties : {};
    for (const name of pathParamNames(route.path)) {
        params.push({ name, in: 'path', required: true, schema: declared[name] || { type: 'string' } });
    }
    const query = route.schemas.query;
    if (query && query.properties) {
        const required = new Set(query.required || []);
        for (const [name, schema] of Object.entries(query.properties)) {
            params.push({ name, in: 'query', required: required.has(name), schema });
        }
    }
    return params;
}

function operationOf(route) {
    const line = accessLine(route);
    const op = {
        operationId: operationId(route),
        tags: [route.group || 'other'],
        description: `Access: ${line.charAt(0).toUpperCase()}${line.slice(1)}.`,
        parameters: parametersOf(route),
        responses: { default: { description: 'The code does not describe the response. Errors use the common JSON error format.' } },
        'x-bf-access': route.gates.filter((g) => ACCESS_AXES.has(g.axis)),
        'x-bf-request-schema': hasSchema(route),
    };
    if (requiresSession(route)) op.security = [{ sessionCookie: [] }, { connectorBearer: [] }];
    if (route.middleware.length) op['x-bf-middleware'] = route.middleware;
    if (op.parameters.length === 0) delete op.parameters;
    if (route.schemas.body) {
        op.requestBody = {
            required: Array.isArray(route.schemas.body.required) && route.schemas.body.required.length > 0,
            content: { 'application/json': { schema: route.schemas.body } },
        };
    }
    if (route.schemas.query && !route.schemas.query.properties) op['x-bf-query-schema'] = route.schemas.query;
    return op;
}

export function buildOpenApi(routes) {
    const paths = {};
    let skipped = 0;
    for (const r of routes) {
        if (!isPlainPath(r.path) || !OPENAPI_METHODS.has(r.method)) { skipped += 1; continue; }
        const key = openapiPath(r.path);
        paths[key] = paths[key] || {};
        paths[key][r.method.toLowerCase()] = operationOf(r);
    }
    const groups = [...new Set(routes.filter((r) => r.group).map((r) => r.group))].sort();
    return sortKeys({
        openapi: '3.1.0',
        info: {
            title: 'Bee Flow server API',
            version: 'unversioned',
            description: `${GENERATED_NOTE} Request schemas are the zod schemas of each route's validate(...); responses are not described. Routes whose path is a regular expression, and routes answering every method, are in the docs pages but not here (${skipped}).`,
        },
        servers: [{ url: '/' }],
        tags: groups.map((name) => ({ name })),
        paths,
        components: {
            securitySchemes: {
                sessionCookie: { type: 'apiKey', in: 'cookie', name: 'connect.sid', description: 'Server-side session cookie set by the login routes. Browsers use this.' },
                connectorBearer: { type: 'http', scheme: 'bearer', bearerFormat: 'JWT', description: 'Short-lived JWT signed with the organisation\'s tenant key, sent with the header X-Beeflow-Source: nextcloud-connector.' },
            },
        },
    });
}

/**
 * JSON with one line per path, so two branches that add different routes touch
 * different lines and merge without a conflict (a one-line file conflicts on
 * every pair; fully indented JSON is five times the size).
 */
export function serializeOpenApi(doc) {
    const { paths, ...rest } = doc;
    const lines = Object.keys(rest).map((k) => `${JSON.stringify(k)}:${JSON.stringify(rest[k])}`);
    const pathLines = Object.keys(paths).map((k) => `${JSON.stringify(k)}:${JSON.stringify(paths[k])}`);
    const head = lines.filter((l) => l < '"paths"');
    const tail = lines.filter((l) => l >= '"paths"');
    const body = [...head, `"paths":{\n${pathLines.join(',\n')}\n}`, ...tail];
    return `{\n${body.join(',\n')}\n}\n`;
}

// ── Markdown ─────────────────────────────────────────────────────────

/** Safe inside MDX prose and table cells. */
export function esc(text) {
    return String(text ?? '')
        .replace(/\s+/g, ' ')
        .replace(/\\/g, '\\\\')
        .replace(/[|{}<>[\]*_`]/g, (c) => `\\${c}`)
        .trim();
}

/** Inside a code span a backtick cannot appear; `|` must still be escaped in a table cell. */
const code = (s) => `\`${String(s).replace(/`/g, "'").replace(/\|/g, '\\|').replace(/\s+/g, ' ')}\``;

const list = (items, max = 12) => {
    const shown = items.slice(0, max).map((v) => code(typeof v === 'string' ? JSON.stringify(v) : JSON.stringify(v)));
    return shown.join(', ') + (items.length > max ? `, … (${items.length} values)` : '');
};

/** A schema's type as a short phrase. */
export function typeOf(schema) {
    if (!schema || typeof schema !== 'object' || Object.keys(schema).length === 0) return 'any';
    if (schema.const !== undefined) return `${code(JSON.stringify(schema.const))}`;
    if (schema.enum) return `one of ${list(schema.enum)}`;
    const variants = schema.anyOf || schema.oneOf;
    if (variants) {
        const parts = [...new Set(variants.map(typeOf))];
        return parts.join(' or ');
    }
    if (schema.allOf) return [...new Set(schema.allOf.map(typeOf))].join(' and ');
    const t = Array.isArray(schema.type) ? schema.type : schema.type ? [schema.type] : [];
    const names = t.map((x) => {
        if (x === 'array') return schema.items ? `array of ${typeOf(schema.items)}` : 'array';
        if (x === 'string' && schema.format) return `string (${schema.format})`;
        return x;
    });
    return names.length ? names.join(' or ') : 'any';
}

function constraintsOf(schema) {
    const out = [];
    const pairs = [['minLength', 'min length'], ['maxLength', 'max length'], ['minimum', 'min'], ['maximum', 'max'], ['exclusiveMinimum', '>'], ['exclusiveMaximum', '<'], ['minItems', 'min items'], ['maxItems', 'max items']];
    for (const [key, label] of pairs) if (typeof schema[key] === 'number') out.push(`${label} ${schema[key]}`);
    if (typeof schema.pattern === 'string') out.push(`pattern ${code(schema.pattern.length > 60 ? `${schema.pattern.slice(0, 57)}...` : schema.pattern)}`);
    if (schema.default !== undefined) {
        const d = JSON.stringify(schema.default);
        if (d !== undefined && d.length <= 60) out.push(`default ${code(d)}`);
    }
    if (schema.additionalProperties === false && schema.type === 'object') out.push('no other keys');
    return out;
}

/**
 * Flatten an object schema into rows: dotted names for nested objects, `[]` for
 * array items that are objects.
 */
export function flattenSchema(schema, prefix = '', depth = 1, rows = []) {
    if (!schema || typeof schema !== 'object') return rows;
    const props = schema.properties;
    if (!props) return rows;
    const required = new Set(schema.required || []);
    for (const [name, prop] of Object.entries(props)) {
        const full = prefix ? `${prefix}.${name}` : name;
        rows.push({ name: full, required: required.has(name), schema: prop });
        const nested = prop.type === 'object' ? prop : prop.type === 'array' && prop.items && prop.items.type === 'object' ? prop.items : null;
        if (nested && nested.properties && depth < MAX_DEPTH) {
            flattenSchema(nested, prop.type === 'array' ? `${full}[]` : full, depth + 1, rows);
        }
    }
    return rows;
}

function partTable(title, schema) {
    if (!schema) return '';
    const rows = flattenSchema(schema);
    if (rows.length === 0) {
        return `**${title}:** ${typeOf(schema)}${constraintsOf(schema).length ? ` (${constraintsOf(schema).join(', ')})` : ''}\n\n`;
    }
    const lines = [`**${title}**`, '', '| Field | Type | Required | Notes |', '|-------|------|:--------:|-------|'];
    for (const row of rows.slice(0, MAX_ROWS)) {
        const notes = [...constraintsOf(row.schema)];
        if (row.schema.description) notes.unshift(esc(row.schema.description));
        lines.push(`| ${code(row.name)} | ${typeOf(row.schema)} | ${row.required ? 'yes' : ''} | ${notes.join('; ')} |`);
    }
    if (rows.length > MAX_ROWS) lines.push('', `${rows.length - MAX_ROWS} more fields: see the full schema in [openapi.json](pathname://${OPENAPI_PUBLIC}).`);
    return `${lines.join('\n')}\n\n`;
}

function routeSection(route) {
    const out = [`### ${code(`${route.method} ${route.path}`)}\n\n`];
    out.push(`**Access:** ${accessLine(route)}\n\n`);
    if (!hasSchema(route)) {
        out.push('No request schema.\n\n');
        return out.join('');
    }
    const params = route.schemas.params && route.schemas.params.properties ? route.schemas.params : null;
    out.push(partTable('Path parameters', params));
    out.push(partTable('Query', route.schemas.query));
    out.push(partTable('Body', route.schemas.body));
    return out.join('');
}

const slugOf = (group) => (group ? group.replace(/\//g, '-') : 'other');

/** group → page slug: groups with enough routes get a page, the rest share `other`. */
export function pageAssignment(routes, minRoutes = MIN_PAGE_ROUTES) {
    const counts = new Map();
    for (const r of routes) counts.set(r.group, (counts.get(r.group) || 0) + 1);
    const pageOf = new Map();
    for (const [group, n] of counts) pageOf.set(group, group && n >= minRoutes ? slugOf(group) : 'other');
    return pageOf;
}

const titleOfPage = (slug, routes) => {
    if (slug === 'other') return 'Other endpoints';
    const sample = routes.find((r) => slugOf(r.group) === slug);
    return `/${sample ? sample.group : slug}`;
};

const frontMatter = (title, extra = '') => `---\ntitle: ${JSON.stringify(title)}\nsidebar_label: ${JSON.stringify(title)}\ncustom_edit_url: null\n${extra}---\n\n{/* ${GENERATED_NOTE} */}\n\n`;

const countLine = (routes) => `${routes.length} route${routes.length === 1 ? '' : 's'}, ${routes.filter(hasSchema).length} with a request schema`;

/**
 * The sub-area of a route inside its page: the path segment after the page's own
 * prefix. Written without a leading slash on purpose, so a heading is never
 * mistaken for a route (server/auth/documentedRoutes.test.js reads every /auth/...
 * in the docs as one).
 */
function sectionKey(route, depth) {
    const segs = route.path.split('/').filter(Boolean).slice(depth);
    const first = segs[0];
    return first && !/^[:*{]/.test(first) ? first : '(root)';
}

function renderPage(slug, routes) {
    if (slug === 'other') routes = [...routes].sort((a, b) => (a.group < b.group ? -1 : a.group > b.group ? 1 : 0));
    const title = titleOfPage(slug, routes);
    const base = slug === 'other' ? 0 : routes[0].group.split('/').length;
    let out = frontMatter(title, 'toc_max_heading_level: 2\n');
    out += `# ${slug === 'other' ? title : code(title)}\n\n${countLine(routes)}. Back to the [endpoint reference](../reference.md).\n\n`;
    let section = null;
    for (const route of routes) {
        const key = slug === 'other' ? (route.group || '(root)') : sectionKey(route, base);
        if (key !== section) {
            section = key;
            out += `## ${code(section)}\n\n`;
        }
        out += routeSection(route);
    }
    return out;
}

function renderIndex(routes, pageOf) {
    const bySlug = new Map();
    for (const r of routes) {
        const slug = pageOf.get(r.group);
        if (!bySlug.has(slug)) bySlug.set(slug, []);
        bySlug.get(slug).push(r);
    }
    const slugs = [...bySlug.keys()].sort((a, b) => (a === 'other' ? 1 : b === 'other' ? -1 : a.localeCompare(b)));
    const withSchema = routes.filter(hasSchema).length;
    let out = frontMatter('Endpoint reference');
    out += '# Endpoint reference\n\n';
    out += `Every route the server mounts, ${routes.length} in all, read from the running app rather than written by hand. ${withSchema} of them declare a request schema (body, query or path parameters), shown below as fields; the other ${routes.length - withSchema} say "No request schema". `;
    out += `The same data as an OpenAPI 3.1 document: [openapi.json](pathname://${OPENAPI_PUBLIC}).\n\n`;
    out += '## How to read it\n\n';
    out += '- **Access** lists what the middleware chain demands: a signed-in user, a permission, a licence feature, a capability, or a named middleware such as `requireAdmin`. A handler can check more inside its body. A route that says "no gate in the middleware chain" is decided by its handler: it checks the session itself, or it is public (login, health, a webhook that verifies a signature).\n';
    out += '- Browsers authenticate with a session cookie; scripts and the Nextcloud connector send a signed bearer JWT. See [Authentication](./auth.md).\n';
    out += '- "No request schema" means the route does not use `validate(...)`; it may still read a body or query by hand.\n';
    out += '- Responses are not described: the code does not declare them. Errors use the [common JSON format](./index.md#error-format).\n';
    out += '- The opt-in MCP endpoints under `/mcp` are listed too; each is mounted only when its flag is set on the server.\n\n';
    out += '## Areas\n\n| Area | Routes | With a request schema |\n|------|-------:|----------------------:|\n';
    for (const slug of slugs) {
        const rs = bySlug.get(slug);
        const label = slug === 'other' ? 'Other endpoints' : code(titleOfPage(slug, routes));
        out += `| [${label}](./reference/${slug}.md) | ${rs.length} | ${rs.filter(hasSchema).length} |\n`;
    }
    out += `| **Total** | **${routes.length}** | **${withSchema}** |\n`;
    return out;
}

/** The whole generated tree: relative path → file content. */
export function buildFiles(raw, { minRoutes = MIN_PAGE_ROUTES } = {}) {
    const routes = normaliseRoutes(raw);
    const pageOf = pageAssignment(routes, minRoutes);
    const files = new Map();
    files.set(OPENAPI_REL, serializeOpenApi(buildOpenApi(routes)));
    const bySlug = new Map();
    for (const r of routes) {
        const slug = pageOf.get(r.group);
        if (!bySlug.has(slug)) bySlug.set(slug, []);
        bySlug.get(slug).push(r);
    }
    for (const [slug, rs] of bySlug) files.set(`${PAGES_REL}/${slug}.md`, renderPage(slug, rs));
    files.set(INDEX_REL, renderIndex(routes, pageOf));
    return { files, routes };
}

export function stats(routes) {
    return { routes: routes.length, withSchema: routes.filter(hasSchema).length };
}

// ── Write / check ────────────────────────────────────────────────────

const listPages = (root) => {
    const dir = path.join(root, PAGES_REL);
    return fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith('.md')).map((f) => `${PAGES_REL}/${f}`) : [];
};

/** Differences between the expected files and the tree: stale, missing, or stray. */
export function diffTree(files, root = ROOT) {
    const problems = [];
    for (const [rel, content] of files) {
        const abs = path.join(root, rel);
        if (!fs.existsSync(abs)) problems.push(`missing: ${rel}`);
        else if (fs.readFileSync(abs, 'utf8') !== content) problems.push(`out of date: ${rel}`);
    }
    for (const rel of listPages(root)) if (!files.has(rel)) problems.push(`no longer generated (delete it): ${rel}`);
    return problems;
}

export function writeTree(files, root = ROOT) {
    for (const rel of listPages(root)) if (!files.has(rel)) fs.rmSync(path.join(root, rel));
    for (const [rel, content] of files) {
        const abs = path.join(root, rel);
        fs.mkdirSync(path.dirname(abs), { recursive: true });
        fs.writeFileSync(abs, content);
    }
}

export function main(argv = process.argv.slice(2)) {
    const check = argv.includes('--check');
    const raw = walkServer();
    const { files, routes } = buildFiles(raw);
    const s = stats(routes);
    if (argv.includes('--stats')) {
        console.log(`${s.routes} routes, ${s.withSchema} with a request schema`);
        return 0;
    }
    if (check) {
        const problems = diffTree(files);
        if (problems.length) {
            console.error(`The API reference is stale:\n${problems.map((p) => `  ${p}`).join('\n')}\nRun \`${REGENERATE}\` and commit the result.`);
            return 1;
        }
        console.log(`✅ API reference is current (${s.routes} routes, ${s.withSchema} with a request schema).`);
        return 0;
    }
    writeTree(files);
    console.log(`Wrote ${files.size} files: ${s.routes} routes, ${s.withSchema} with a request schema.`);
    return 0;
}

if (isEntryPoint(import.meta.url)) {
    try {
        process.exit(main());
    } catch (err) {
        console.error(err instanceof Error ? err.message : err);
        process.exit(2);
    }
}
